requestDocument(projectId, document.id, controller.signal)
      .then((response) => {
        if (controller.signal.aborted) {
          return;
        }

        setState({
          detail: assertDocumentDetailResponse(
            response,
            projectId,
            document.id,
          ),
          error: null,
          status: 'ready',
        });
      })
      .catch

listRequest(projectId, controller.signal)
      .then((response) => {
        if (
          controller.signal.aborted ||
          operation !== listOperationRef.current ||
          activeProjectIdRef.current !== projectId
        ) {
          return;
        }

        const loaded = assertDocumentListResponse(response, projectId);
        const documents =
          mutationRevision === mutationRevisionRef.current
            ? [...loaded]
            : mergeDocuments(loaded, documentsRef.current);
        documentsRef.current = documents;
        setStore({
          documents,
          error: null,
          projectId,
          status: 'ready',
        });
      })
      .catch((error: unknown) => {
        if (
          controller.signal.aborted ||
          operation !== listOperationRef.current ||
          activeProjectIdRef.current !== projectId ||
          isAbort(error)
        ) {
          return;
        }

        setStore((current) => ({
          documents:
            current.projectId === projectId ? current.documents : [],
          error: errorMessage(
            error,
            'The documents could not be loaded. Please retry.',
          ),
          projectId,
          status: 'error',
        }));
      })
      .finally

